const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length < 2) return;

    const p = input[0];
    const a = input[1];

    const countP = {};
    for (let i = 0; i < p.length; i++) {
        const char = p[i];
        countP[char] = (countP[char] || 0) + 1;
    }

    const countA = {};
    for (let i = 0; i < a.length; i++) {
        const char = a[i];
        if (char !== '*') {
            countA[char] = (countA[char] || 0) + 1;
        }
    }

    let possible = true;
    for (const char in countA) {
        if (!countP[char] || countA[char] > countP[char]) {
            possible = false;
            break;
        }
    }

    console.log(possible ? 'S' : 'N');
}

solve();
